import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.B5WAEDB7.js";const s="/assets/images/5KeocQs.jpg",n="/assets/images/JdAsdvG.jpg",i="/assets/images/yzDrJtA.jpg",l="/assets/images/iF4Mkb5.png",b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/communication.md","filePath":"core-concepts/communication.md"}'),c={name:"core-concepts/communication.md"};function d(p,e,h,u,g,m){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Communication.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+s+'"><br><i><a href="http://www.escotal.com/osilayer.html">Source: OSI 7 layer model</a></i></p><h3 id="hypertext-transfer-protocol-http" tabindex="-1">Hypertext transfer protocol (HTTP) <a class="header-anchor" href="#hypertext-transfer-protocol-http" aria-label="Permalink to &quot;Hypertext transfer protocol (HTTP)&quot;">​</a></h3><p>HTTP is a method for encoding and transporting data between a client and a server. It is a request/response protocol: clients issue requests and servers issue responses with relevant content and completion status info about the request. HTTP is self-contained, allowing requests and responses to flow through many intermediate routers and servers that perform load balancing, caching, encryption, and compression.</p><p>A basic HTTP request consists of a verb (method) and a resource (endpoint). Below are common HTTP verbs:</p><table tabindex="0"><thead><tr><th>Verb</th><th>Description</th><th>Idempotent*</th><th>Safe</th><th>Cacheable</th></tr></thead><tbody><tr><td>GET</td><td>Reads a resource</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>POST</td><td>Creates a resource or trigger a process that handles data</td><td>No</td><td>No</td><td>Yes if response contains freshness info</td></tr><tr><td>PUT</td><td>Creates or replace a resource</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>PATCH</td><td>Partially updates a resource</td><td>No</td><td>No</td><td>Yes if response contains freshness info</td></tr><tr><td>DELETE</td><td>Deletes a resource</td><td>Yes</td><td>No</td><td>No</td></tr></tbody></table><p>*Can be called many times without different outcomes.</p><p>HTTP is an application layer protocol relying on lower-level protocols such as <strong>TCP</strong> and <strong>UDP</strong>.</p><h4 id="source-s-and-further-reading-http" tabindex="-1">Source(s) and further reading: HTTP <a class="header-anchor" href="#source-s-and-further-reading-http" aria-label="Permalink to &quot;Source(s) and further reading: HTTP&quot;">​</a></h4><ul><li><a href="https://www.nginx.com/resources/glossary/http/" target="_blank" rel="noreferrer">What is HTTP?</a></li><li><a href="https://www.quora.com/What-is-the-difference-between-HTTP-protocol-and-TCP-protocol" target="_blank" rel="noreferrer">Difference between HTTP and TCP</a></li><li><a href="https://laracasts.com/discuss/channels/general-discussion/whats-the-differences-between-put-and-patch?page=1" target="_blank" rel="noreferrer">Difference between PUT and PATCH</a></li></ul><h3 id="transmission-control-protocol-tcp" tabindex="-1">Transmission control protocol (TCP) <a class="header-anchor" href="#transmission-control-protocol-tcp" aria-label="Permalink to &quot;Transmission control protocol (TCP)&quot;">​</a></h3><p align="center"><img src="'+n+'"><br><i><a href="http://www.wildbunny.co.uk/blog/2012/10/09/how-to-make-a-multi-player-game-part-1/">Source: How to make a multiplayer game</a></i></p><p>TCP is a connection-oriented protocol over an <a href="https://en.wikipedia.org/wiki/Internet_Protocol" target="_blank" rel="noreferrer">IP network</a>. Connection is established and terminated using a <a href="https://en.wikipedia.org/wiki/Handshaking" target="_blank" rel="noreferrer">handshake</a>. All packets sent are guaranteed to reach the destination in the original order and without corruption through:</p><ul><li>Sequence numbers and <a href="https://en.wikipedia.org/wiki/Transmission_Control_Protocol#Checksum_computation" target="_blank" rel="noreferrer">checksum fields</a> for each packet</li><li><a href="https://en.wikipedia.org/wiki/Acknowledgement_(data_networks)" target="_blank" rel="noreferrer">Acknowledgement</a> packets and automatic retransmission</li></ul><p>If the sender does not receive a correct response, it will resend the packets. If there are multiple timeouts, the connection is dropped. TCP also implements <a href="https://en.wikipedia.org/wiki/Flow_control_(data)" target="_blank" rel="noreferrer">flow control</a> and <a href="https://en.wikipedia.org/wiki/Network_congestion#Congestion_control" target="_blank" rel="noreferrer">congestion control</a>. These guarantees cause delays and generally result in less efficient transmission than UDP.</p><p>To ensure high throughput, web servers can keep a large number of TCP connections open, resulting in high memory usage. It can be expensive to have a large number of open connections between web server threads and say, a <a href="https://memcached.org/" target="_blank" rel="noreferrer">memcached</a> server. <a href="https://en.wikipedia.org/wiki/Connection_pool" target="_blank" rel="noreferrer">Connection pooling</a> can help in addition to switching to UDP where applicable.</p><p>TCP is useful for applications that require high reliability but are less time critical. Some examples include web servers, database info, SMTP, FTP, and SSH.</p><p>Use TCP over UDP when:</p><ul><li>You need all of the data to arrive intact</li><li>You want to automatically make a best estimate use of the network throughput</li></ul><h3 id="user-datagram-protocol-udp" tabindex="-1">User datagram protocol (UDP) <a class="header-anchor" href="#user-datagram-protocol-udp" aria-label="Permalink to &quot;User datagram protocol (UDP)&quot;">​</a></h3><p align="center"><img src="'+i+'"><br><i><a href="http://www.wildbunny.co.uk/blog/2012/10/09/how-to-make-a-multi-player-game-part-1/">Source: How to make a multiplayer game</a></i></p><p>UDP is connectionless. Datagrams (analogous to packets) are guaranteed only at the datagram level. Datagrams might reach their destination out of order or not at all. UDP does not support congestion control. Without the guarantees that TCP support, UDP is generally more efficient.</p><p>UDP can broadcast, sending datagrams to all devices on the subnet. This is useful with <a href="https://en.wikipedia.org/wiki/Dynamic_Host_Configuration_Protocol" target="_blank" rel="noreferrer">DHCP</a> because the client has not yet received an IP address, thus preventing a way for TCP to stream without the IP address.</p><p>UDP is less reliable but works well in real time use cases such as VoIP, video chat, streaming, and realtime multiplayer games.</p><p>Use UDP over TCP when:</p><ul><li>You need the lowest latency</li><li>Late data is worse than loss of data</li><li>You want to implement your own error correction</li></ul><h4 id="source-s-and-further-reading-tcp-and-udp" tabindex="-1">Source(s) and further reading: TCP and UDP <a class="header-anchor" href="#source-s-and-further-reading-tcp-and-udp" aria-label="Permalink to &quot;Source(s) and further reading: TCP and UDP&quot;">​</a></h4><ul><li><a href="https://gafferongames.com/post/udp_vs_tcp/" target="_blank" rel="noreferrer">Networking for game programming</a></li><li><a href="http://www.cyberciti.biz/faq/key-differences-between-tcp-and-udp-protocols/" target="_blank" rel="noreferrer">Key differences between TCP and UDP protocols</a></li><li><a href="http://stackoverflow.com/questions/5970383/difference-between-tcp-and-udp" target="_blank" rel="noreferrer">Difference between TCP and UDP</a></li><li><a href="https://en.wikipedia.org/wiki/Transmission_Control_Protocol" target="_blank" rel="noreferrer">Transmission control protocol</a></li><li><a href="https://en.wikipedia.org/wiki/User_Datagram_Protocol" target="_blank" rel="noreferrer">User datagram protocol</a></li><li><a href="http://www.cs.bu.edu/~jappavoo/jappavoo.github.com/451/papers/memcache-fb.pdf" target="_blank" rel="noreferrer">Scaling memcache at Facebook</a></li></ul><h3 id="remote-procedure-call-rpc" tabindex="-1">Remote procedure call (RPC) <a class="header-anchor" href="#remote-procedure-call-rpc" aria-label="Permalink to &quot;Remote procedure call (RPC)&quot;">​</a></h3><p align="center"><img src="'+l+`"><br><i><a href="http://www.puncsky.com/blog/2016-02-13-crack-the-system-design-interview">Source: Crack the system design interview</a></i></p><p>In an RPC, a client causes a procedure to execute on a different address space, usually a remote server. The procedure is coded as if it were a local procedure call, abstracting away the details of how to communicate with the server from the client program. Remote calls are usually slower and less reliable than local calls so it is helpful to distinguish RPC calls from local calls. Popular RPC frameworks include <a href="https://developers.google.com/protocol-buffers/" target="_blank" rel="noreferrer">Protobuf</a>, <a href="https://thrift.apache.org/" target="_blank" rel="noreferrer">Thrift</a>, and <a href="https://avro.apache.org/docs/current/" target="_blank" rel="noreferrer">Avro</a>.</p><p>RPC is a request-response protocol:</p><ul><li><strong>Client program</strong> - Calls the client stub procedure. The parameters are pushed onto the stack like a local procedure call.</li><li><strong>Client stub procedure</strong> - Marshals (packs) procedure id and arguments into a request message.</li><li><strong>Client communication module</strong> - OS sends the message from the client to the server.</li><li><strong>Server communication module</strong> - OS passes the incoming packets to the server stub procedure.</li><li><strong>Server stub procedure</strong> - Unmarshalls the results, calls the server procedure matching the procedure id and passes the given arguments.</li><li>The server response repeats the steps above in reverse order.</li></ul><p>Sample RPC calls:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /someoperation?data=anId</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /anotheroperation</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;data&quot;:&quot;anId&quot;;</span></span>
<span class="line"><span>  &quot;anotherdata&quot;: &quot;another value&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>RPC is focused on exposing behaviors. RPCs are often used for performance reasons with internal communications, as you can hand-craft native calls to better fit your use cases.</p><p>Choose a native library (aka SDK) when:</p><ul><li>You know your target platform.</li><li>You want to control how your &quot;logic&quot; is accessed.</li><li>You want to control how error control happens off your library.</li><li>Performance and end user experience is your primary concern.</li></ul><p>HTTP APIs following <strong>REST</strong> tend to be used more often for public APIs.</p><h4 id="disadvantage-s-rpc" tabindex="-1">Disadvantage(s): RPC <a class="header-anchor" href="#disadvantage-s-rpc" aria-label="Permalink to &quot;Disadvantage(s): RPC&quot;">​</a></h4><ul><li>RPC clients become tightly coupled to the service implementation.</li><li>A new API must be defined for every new operation or use case.</li><li>It can be difficult to debug RPC.</li><li>You might not be able to leverage existing technologies out of the box. For example, it might require additional effort to ensure <a href="https://web.archive.org/web/20170608193645/http://etherealbits.com/2012/12/debunking-the-myths-of-rpc-rest/" target="_blank" rel="noreferrer">RPC calls are properly cached</a> on caching servers such as <a href="http://www.squid-cache.org/" target="_blank" rel="noreferrer">Squid</a>.</li></ul><h3 id="representational-state-transfer-rest" tabindex="-1">Representational state transfer (REST) <a class="header-anchor" href="#representational-state-transfer-rest" aria-label="Permalink to &quot;Representational state transfer (REST)&quot;">​</a></h3><p>REST is an architectural style enforcing a client/server model where the client acts on a set of resources managed by the server. The server provides a representation of resources and actions that can either manipulate or get a new representation of resources. All communication must be stateless and cacheable.</p><p>There are four qualities of a RESTful interface:</p><ul><li><strong>Identify resources (URI in HTTP)</strong> - use the same URI regardless of any operation.</li><li><strong>Change with representations (Verbs in HTTP)</strong> - use verbs, headers, and body.</li><li><strong>Self-descriptive error message (status response in HTTP)</strong> - Use status codes, don&#39;t reinvent the wheel.</li><li><strong><a href="http://restcookbook.com/Basics/hateoas/" target="_blank" rel="noreferrer">HATEOAS</a> (HTML interface for HTTP)</strong> - your web service should be fully accessible in a browser.</li></ul><p>Sample REST calls:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /someresources/anId</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PUT /someresources/anId</span></span>
<span class="line"><span>{&quot;anotherdata&quot;: &quot;another value&quot;}</span></span></code></pre></div><p>REST is focused on exposing data. It minimizes the coupling between client/server and is often used for public HTTP APIs. REST uses a more generic and uniform method of exposing resources through URIs, <a href="https://github.com/for-GET/know-your-http-well/blob/master/headers.md" target="_blank" rel="noreferrer">representation through headers</a>, and actions through verbs such as GET, POST, PUT, DELETE, and PATCH. Being stateless, REST is great for horizontal scaling and partitioning.</p><h4 id="disadvantage-s-rest" tabindex="-1">Disadvantage(s): REST <a class="header-anchor" href="#disadvantage-s-rest" aria-label="Permalink to &quot;Disadvantage(s): REST&quot;">​</a></h4><ul><li>With REST being focused on exposing data, it might not be a good fit if resources are not naturally organized or accessed in a simple hierarchy. For example, returning all updated records from the past hour matching a particular set of events is not easily expressed as a path. With REST, it is likely to be implemented with a combination of URI path, query parameters, and possibly the request body.</li><li>REST typically relies on a few verbs (GET, POST, PUT, DELETE, and PATCH) which sometimes doesn&#39;t fit your use case. For example, moving expired documents to the archive folder might not cleanly fit within these verbs.</li><li>Fetching complicated resources with nested hierarchies requires multiple round trips between the client and server to render single views, e.g. fetching content of a blog entry and the comments on that entry. For mobile applications operating in variable network conditions, these multiple roundtrips are highly undesirable.</li><li>Over time, more fields might be added to an API response and older clients will receive all new data fields, even those that they do not need, as a result, it bloats the payload size and leads to larger latencies.</li></ul><h3 id="rpc-and-rest-calls-comparison" tabindex="-1">RPC and REST calls comparison <a class="header-anchor" href="#rpc-and-rest-calls-comparison" aria-label="Permalink to &quot;RPC and REST calls comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>RPC</th><th>REST</th></tr></thead><tbody><tr><td>Signup</td><td><strong>POST</strong> /signup</td><td><strong>POST</strong> /persons</td></tr><tr><td>Resign</td><td><strong>POST</strong> /resign<br>{<br>&quot;personid&quot;: &quot;1234&quot;<br>}</td><td><strong>DELETE</strong> /persons/1234</td></tr><tr><td>Read a person</td><td><strong>GET</strong> /readPerson?personid=1234</td><td><strong>GET</strong> /persons/1234</td></tr><tr><td>Read a person’s items list</td><td><strong>GET</strong> /readUsersItemsList?personid=1234</td><td><strong>GET</strong> /persons/1234/items</td></tr><tr><td>Add an item to a person’s items</td><td><strong>POST</strong> /addItemToUsersItemsList<br>{<br>&quot;personid&quot;: &quot;1234&quot;;<br>&quot;itemid&quot;: &quot;456&quot;<br>}</td><td><strong>POST</strong> /persons/1234/items<br>{<br>&quot;itemid&quot;: &quot;456&quot;<br>}</td></tr><tr><td>Update an item</td><td><strong>POST</strong> /modifyItem<br>{<br>&quot;itemid&quot;: &quot;456&quot;;<br>&quot;key&quot;: &quot;value&quot;<br>}</td><td><strong>PUT</strong> /items/456<br>{<br>&quot;key&quot;: &quot;value&quot;<br>}</td></tr><tr><td>Delete an item</td><td><strong>POST</strong> /removeItem<br>{<br>&quot;itemid&quot;: &quot;456&quot;<br>}</td><td><strong>DELETE</strong> /items/456</td></tr></tbody></table><p align="center"><i><a href="https://apihandyman.io/do-you-really-know-why-you-prefer-rest-over-rpc/">Source: Do you really know why you prefer REST over RPC</a></i></p><h4 id="source-s-and-further-reading-rest-and-rpc" tabindex="-1">Source(s) and further reading: REST and RPC <a class="header-anchor" href="#source-s-and-further-reading-rest-and-rpc" aria-label="Permalink to &quot;Source(s) and further reading: REST and RPC&quot;">​</a></h4><ul><li><a href="https://apihandyman.io/do-you-really-know-why-you-prefer-rest-over-rpc/" target="_blank" rel="noreferrer">Do you really know why you prefer REST over RPC</a></li><li><a href="http://programmers.stackexchange.com/a/181186" target="_blank" rel="noreferrer">When are RPC-ish approaches more appropriate than REST?</a></li><li><a href="http://stackoverflow.com/questions/15056878/rest-vs-json-rpc" target="_blank" rel="noreferrer">REST vs JSON-RPC</a></li><li><a href="https://web.archive.org/web/20170608193645/http://etherealbits.com/2012/12/debunking-the-myths-of-rpc-rest/" target="_blank" rel="noreferrer">Debunking the myths of RPC and REST</a></li><li><a href="https://www.quora.com/What-are-the-drawbacks-of-using-RESTful-APIs" target="_blank" rel="noreferrer">What are the drawbacks of using REST</a></li><li><a href="http://www.puncsky.com/blog/2016-02-13-crack-the-system-design-interview" target="_blank" rel="noreferrer">Crack the system design interview</a></li><li><a href="https://code.facebook.com/posts/1468950976659943/" target="_blank" rel="noreferrer">Thrift</a></li><li><a href="http://arstechnica.com/civis/viewtopic.php?t=1190508" target="_blank" rel="noreferrer">Why REST for internal use and not RPC</a></li></ul>`,56)])])}const w=t(c,[["render",d]]);export{b as __pageData,w as default};
